text:
Use `pg` pool. Key config:

```js
import { Pool } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 20,          // max connections (default 10)
  min: 2,           // keep alive when idle
  idleTimeoutMillis: 30_000,    // kill idle conn after 30s
  connectionTimeoutMillis: 5_000, // fail fast if can't connect in 5s
  allowExitOnIdle: true,        // let process exit if pool idle
});

// Error handler — REQUIRED. Unhandled 'error' event crashes process.
pool.on('error', (err, client) => {
  console.error('Idle client error:', err.message);
});

// Query helper — auto-release client
async function query(sql, params) {
  const start = Date.now();
  try {
    const res = await pool.query(sql, params);
    console.debug('Query time:', Date.now() - start, 'ms');
    return res;
  } catch (err) {
    console.error('Query failed:', err.message, { sql, params });
    throw err;
  }
}

// Transaction helper — manual checkout needed
async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // ALWAYS release — else pool starves
  }
}

// Graceful shutdown
async function shutdown() {
  await pool.end();
  console.log('Pool closed.');
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

export { pool, query, withTransaction };
```

## Key decisions

| Config | Why |
|--------|-----|
| `max: 20` | Match Postgres `max_connections` minus headroom for admin/migrations |
| `connectionTimeoutMillis` | Fail fast > hang forever. 2–5s typical |
| `idleTimeoutMillis` | Free unused conn. Match load pattern |
| `pool.on('error')` | Without this, idle client error = uncaught exception = crash |
| `finally { client.release() }` | Leak one client → pool starves under load |

## Tune pool size

```
pool size ≈ (core_count * 2) + effective_spindle_count
```
Postgres default `max_connections = 100`. Leave ~10 for admin. Split remainder across app instances.

## Health check

```js
async function healthCheck() {
  const client = await pool.connect();
  try {
    await client.query('SELECT 1');
    return { status: 'ok', total: pool.totalCount, idle: pool.idleCount, waiting: pool.waitingCount };
  } finally {
    client.release();
  }
}
```
